def _fallback_flags(repo: Path, language: str) -> tuple[list[str], dict[str, Any]]:
    """Resolve a unique language standard from build files or use the bounded default."""
    candidates: set[str] = set()
    evidence: list[dict[str, str]] = []
    patterns = (
        ((r"CXX_STANDARD\s+([0-9]+)", r"cxx_std_([0-9]+)", r"-std=c\+\+([0-9]+)"), "c++")
        if language == "cpp"
        else ((r"(?<!X)C_STANDARD\s+([0-9]+)", r"c_std_([0-9]+)", r"-std=c([0-9]+)"), "c")
    )
    regexes, prefix = patterns
    build_names = {"CMakeLists.txt", "meson.build", "Makefile", "makefile", "SConstruct", "SConscript"}
    paths = [path for path in repo.rglob("*") if path.is_file() and (path.name in build_names or path.suffix.lower() in {".cmake", ".vcxproj", ".mk"})]
    for path in sorted(paths)[:500]:
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        for pattern in regexes:
            for match in re.finditer(pattern, text, flags=re.IGNORECASE):
                value = match.group(1)
                standard = f"{prefix}{value}"
                candidates.add(standard)
                evidence.append({"path": path.relative_to(repo).as_posix(), "match": match.group(0), "standard": standard})
    default_standard = "c17" if language == "c" else "c++17"
    selected = next(iter(candidates)) if len(candidates) == 1 else default_standard
    resolution = "build-config-unique" if len(candidates) == 1 else ("fallback-no-evidence" if not candidates else "fallback-ambiguous-evidence")
    flags = ["-x", "c" if language == "c" else "c++", f"-std={selected}"]
    return flags, {"resolution": resolution, "candidates": sorted(candidates), "matches": evidence, "selected": selected}

def _flatten_symbols(values: Any) -> list[dict[str, Any]]:
    result: list[dict[str, Any]] = []
    if not isinstance(values, list):
        return result
    for item in values:
        if not isinstance(item, dict):
            continue
        result.append(item)
        result.extend(_flatten_symbols(item.get("children")))
    return result

def collect_semantics(
    repo: Path,
    language: str,
    files: list[dict[str, Any]],
    entities: list[dict[str, Any]],
    options: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if os.environ.get("CKB_TEST_PROVIDER") == "deterministic-fixture":
        covered = [e["id"] for e in entities if e["kind"] != "file" and e["language"] == language]
        return {
            "provider": {"name": "deterministic-fixture", "language": language, "status": "passed", "precision": "test-only", "covered_entity_ids": covered},
            "links": [],
            "diagnostics": [],
            "transcript": [],
            "stderr": [],
        }
    command, language_id, initialization, precision, server_cwd, environment = _provider_spec(language, repo, options)
    document_root = Path(((options or {}).get("csharp_workspace") or {}).get("workspace_root") or repo).resolve() if language == "csharp" else repo
    client = LspClient(command, server_cwd, environment)
    client.start()
    result_payload: dict[str, Any] | None = None
    diagnostics: list[dict[str, Any]] = []
    symbol_counts: dict[str, int] = {}
    covered: set[str] = set()
    semantic_links: list[dict[str, Any]] = []
    entity_by_position: dict[tuple[str, int], list[dict[str, Any]]] = {}
    for entity in entities:
        entity_by_position.setdefault((entity["path"], entity["range"].get("name_line", entity["range"]["start_line"]) - 1), []).append(entity)
    try:
        result = client.request(
            "initialize",
            {
                "processId": os.getpid(),
                "rootUri": path_to_uri(document_root),
                "workspaceFolders": [{"uri": path_to_uri(document_root), "name": document_root.name}],
                "capabilities": {"workspace": {"configuration": True}, "textDocument": {"documentSymbol": {"hierarchicalDocumentSymbolSupport": True}}},
                "initializationOptions": initialization,
            },
            timeout=90,
        )
        client.notify("initialized", {})
        for file_entry in files:
            path = (document_root / file_entry["path"]).resolve()
            uri = path_to_uri(path)
            text = path.read_text(encoding="utf-8", errors="replace")
            client.notify(
                "textDocument/didOpen",
                {"textDocument": {"uri": uri, "languageId": language_id, "version": 1, "text": text}},
            )
            symbols = client.request("textDocument/documentSymbol", {"textDocument": {"uri": uri}}, timeout=90)
            flat = _flatten_symbols(symbols)
            symbol_counts[file_entry["path"]] = len(flat)
            for item in flat:
                selection = item.get("selectionRange") or item.get("range") or {}
                start = selection.get("start") or {}
                for entity in entity_by_position.get((file_entry["path"], int(start.get("line", -1))), []):
                    if entity["name"] == item.get("name") or entity["name"] in str(item.get("name", "")):
                        covered.add(entity["id"])
            for entity in [e for e in entities if e["path"] == file_entry["path"] and e["kind"] != "file" and e["candidate_classification"] == "page"]:
                position = {"line": entity["range"].get("name_line", entity["range"]["start_line"]) - 1, "character": entity["range"].get("name_column_utf8", 0)}
                try:
                    definitions = client.request("textDocument/definition", {"textDocument": {"uri": uri}, "position": position}, timeout=30)
                    references = client.request("textDocument/references", {"textDocument": {"uri": uri}, "position": position, "context": {"includeDeclaration": False}}, timeout=30)
                except CkbError:
                    definitions, references = [], []
                if definitions:
                    covered.add(entity["id"])
                for location in references or []:
                    target_uri = location.get("uri") or (location.get("targetUri") if isinstance(location, dict) else None)
                    target_range = location.get("range") or location.get("targetSelectionRange") or {}
                    if not target_uri:
                        continue
                    try:
                        rel = uri_to_path(target_uri).relative_to(document_root).as_posix()
                    except ValueError:
                        continue
                    line = int((target_range.get("start") or {}).get("line", -1))
                    for source_entity in entity_by_position.get((rel, line), []):
                        if source_entity["id"] == entity["id"]:
                            continue
                        semantic_links.append({
                            "id": stable_id("link", source_entity["id"], entity["id"], "references", language),
                            "type": "references",
                            "source": source_entity["id"],
                            "target": entity["id"],
                            "provider": command[0],
                            "evidence": {"uri": target_uri, "line": line, "queried_entity": entity["id"]},
                        })
        time.sleep(0.2)
        for event in client.transcript:
            message = event.get("message", {})
            if event.get("direction") == "in" and message.get("method") == "textDocument/publishDiagnostics":
                params = message.get("params", {})
                diagnostics.extend(params.get("diagnostics", []))
        fatal_patterns = (
            "invalid ast",
            "file not found",
            "could not build compilerinvocation",
            "pp_file_not_found",
            "failed to create target",
            "could not be loaded",
            "project file does not exist",
            "assets file",
            "failed to load project",
            "failed to load solution",
        )
        fatal = [d for d in diagnostics if any(p in str(d.get("message", "")).lower() for p in fatal_patterns)]
        fatal_stderr = [line for line in client.stderr if any(pattern in line.lower() for pattern in fatal_patterns)]
        warnings: list[dict[str, Any]] = []
        if language in {"c", "cpp"} and precision == "bounded-approximate":
            fallback_evidence = initialization.get("fallbackEvidence", {})
            warnings.append(
                {
                    "kind": "compile-commands-unavailable",
                    "language": language,
                    "file": "compile_commands.json",
                    "precision": "bounded-approximate",
                    "build_evidence": {
                        "resolution": fallback_evidence.get("resolution"),
                        "selected": fallback_evidence.get("selected"),
                        "paths": sorted({str(item.get("path")) for item in fallback_evidence.get("matches", []) if item.get("path")}),
                    },
                    "absence_inference_allowed": False,
                    "message_zh": "未找到 compile_commands.json，语义提供器继续使用有界近似参数；未检出结果不等于源码事实不存在。",
                }
            )
        provider = {
            "name": Path(command[0]).name,
            "language": language,
            "command": command,
            "initialization_options": initialization,
            "server_cwd": str(server_cwd),
            "document_root": str(document_root),
            "precision": precision,
            "status": _provider_status(fatal, fatal_stderr),
            "covered_entity_ids": sorted(covered),
            "document_symbol_counts": symbol_counts,
            "diagnostic_count": len(diagnostics),
            "fatal_diagnostics": fatal,
            "fatal_stderr": fatal_stderr,
            "warnings": warnings,
            "capabilities": result.get("capabilities", {}) if isinstance(result, dict) else {},
        }
        result_payload = {"provider": provider, "links": semantic_links, "diagnostics": diagnostics, "transcript": client.transcript, "stderr": client.stderr}
        return result_payload
    finally:
        exit_status = client.stop()
        if result_payload is not None:
            result_payload["provider"]["exit_status"] = exit_status

def _split_camel(value: str) -> list[str]:
    return [
        part
        for part in re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", value).replace("::", " ").split()
        if part
    ]

def _ranked_terms(text: str) -> list[str]:
    normalized = unicodedata.normalize("NFKC", text)
    priorities: dict[str, int] = {}

    def add(value: str, priority: int) -> None:
        if value:
            priorities[value] = min(priorities.get(value, priority), priority)

    for run in _CODE_RUN.findall(normalized):
        lowered = run.casefold().strip("._$:/\\#+-")
        if len(lowered) >= 2:
            add(lowered, 0)
        for part in _CODE_SEPARATOR.split(run):
            if len(part) >= 2:
                add(part.casefold(), 1)
            for camel in _split_camel(part):
                if len(camel) >= 2:
                    add(camel.casefold(), 1)

    for run in _CJK_RUN.findall(normalized):
        # Preserve the complete phrase, including a single explicit Han
        # character.  FTS filtering separately requires at least three code
        # points because every CKB FTS table uses the trigram tokenizer.
        add(run, 0)
        for span in (value for value in _CJK_GLUE_RUN.split(run) if value):
            if len(span) >= 2:
                add(span, 1)
            for width, priority in ((3, 2), (2, 3)):
                for index in range(max(0, len(span) - width + 1)):
                    add(span[index : index + width], priority)

    return sorted(priorities, key=lambda value: (priorities[value], -len(value), value))

def add(value: str, priority: int) -> None:
        if value:
            priorities[value] = min(priorities.get(value, priority), priority)

def index_terms(text: str) -> list[str]:
    """Return the same deterministic terms without the query-side cap."""
    return _ranked_terms(text)

def fts_query_terms(text: str, limit: int = DEFAULT_FTS_TERM_LIMIT) -> list[str]:
    """Select trigram-compatible terms from the bounded query ordering."""
    if limit < 0:
        raise ValueError("FTS term limit must be non-negative")
    return [term for term in search_terms(text) if len(term) >= 3][:limit]

def build_fts_query(text: str, limit: int = DEFAULT_FTS_TERM_LIMIT) -> str | None:
    values = fts_query_terms(text, limit)
    if not values:
        return None
    return " OR ".join('"' + value.replace('"', '""') + '"' for value in values)

def explicit_anchors(text: str) -> list[str]:
    """Retain explicit code anchors independently from prose term ranking."""
    normalized = unicodedata.normalize("NFKC", text)
    anchors: set[str] = set()
    for value in re.findall(
        r"[A-Za-z_][A-Za-z0-9_]*(?:(?:::|[./#$:-])[A-Za-z0-9_]+)+|[A-Za-z_][A-Za-z0-9_]{2,}",
        normalized,
    ):
        if (
            any(character.isupper() for character in value[1:])
            or any(character in value for character in "_./#$:-")
            or any(character.isdigit() for character in value)
        ):
            anchors.add(value.casefold())
    return sorted(anchors)

class RecordReplaceLockError(CkbError):
    def __init__(self, category: str, message: str):
        super().__init__(f"{category}: {message}")
        self.category = category

def __init__(self, category: str, message: str):
        super().__init__(f"{category}: {message}")
        self.category = category

def _json_digest(value: Any) -> str:
    payload = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()

def _new_replace_lock_record(owner_token: str) -> dict[str, Any]:
    state, identity = _process_start_identity(os.getpid())
    if state != "alive" or not identity:
        raise RecordReplaceLockError(
            "record-replace-lock-owner-identity-unavailable",
            f"current process identity is unavailable for record replacement lock: {os.getpid()}",
        )
    return {
        "schema_version": REPLACE_LOCK_SCHEMA_VERSION,
        "owner_pid": os.getpid(),
        "owner_token": owner_token,
        "owner_process_start": identity,
        "owner_host": socket.gethostname(),
        "created_at_utc": utc_now(),
    }

def _parse_replace_lock(value: bytes) -> tuple[dict[str, Any] | None, str | None]:
    try:
        record = json.loads(value.decode("utf-8-sig"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None, "record-replace-lock-record-invalid"
    if not isinstance(record, dict) or set(record) != REPLACE_LOCK_FIELDS:
        return None, "record-replace-lock-record-invalid"
    if record.get("schema_version") != REPLACE_LOCK_SCHEMA_VERSION:
        return None, "record-replace-lock-record-invalid"
    if not isinstance(record.get("owner_pid"), int) or record["owner_pid"] < 1:
        return None, "record-replace-lock-record-invalid"
    if not isinstance(record.get("owner_token"), str) or not REPLACE_OWNER_TOKEN_PATTERN.fullmatch(record["owner_token"]):
        return None, "record-replace-lock-record-invalid"
    for field in ("owner_process_start", "owner_host", "created_at_utc"):
        if not isinstance(record.get(field), str) or not record[field] or len(record[field]) > 128:
            return None, "record-replace-lock-record-invalid"
    return record, None

def _replace_lock_owner_state(record: dict[str, Any]) -> str:
    if record["owner_host"] != socket.gethostname():
        return "record-replace-lock-owner-unverifiable"
    state, identity = _process_start_identity(int(record["owner_pid"]))
    if state == "dead":
        return "record-replace-lock-owner-dead"
    if state != "alive" or not identity:
        return "record-replace-lock-owner-unverifiable"
    if identity != record["owner_process_start"]:
        return "record-replace-lock-owner-pid-reused"
    return "record-replace-lock-owner-live"

def _release_replace_lock(lock: Path, descriptor: int, owner_token: str) -> None:
    category: str | None = None
    try:
        if not _same_owner_lock_file(lock, descriptor):
            category = "record-replace-lock-release-file-replaced"
        else:
            record, invalid = _parse_replace_lock(_owner_descriptor_bytes(descriptor))
            if invalid or record is None or record.get("owner_token") != owner_token:
                category = "record-replace-lock-release-owner-token-drift"
    finally:
        _owner_descriptor_unlock(descriptor)
        os.close(descriptor)
    if category is None:
        try:
            record, invalid = _parse_replace_lock(lock.read_bytes())
        except FileNotFoundError:
            category = "record-replace-lock-release-missing"
        else:
            if invalid or record is None or record.get("owner_token") != owner_token:
                category = "record-replace-lock-release-owner-token-drift"
            else:
                lock.unlink()
    if category:
        raise RecordReplaceLockError(category, f"record replacement lock ownership changed before release: {lock}")

def _replace_lock(output: Path) -> Iterator[dict[str, Any]]:
    root = _operation_root(output)
    root.mkdir(parents=True, exist_ok=True)
    lock = root / ".lock"
    deadline = time.monotonic() + REPLACE_LOCK_TIMEOUT_SECONDS
    owner_token = uuid.uuid4().hex
    descriptor: int | None = None
    recovered_category: str | None = None
    last_category = "concurrent-record-replace-lock"
    while descriptor is None:
        created = False
        try:
            candidate = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_RDWR, 0o600)
            created = True
            os.write(candidate, b" ")
        except FileExistsError:
            try:
                candidate = os.open(lock, os.O_RDWR)
            except FileNotFoundError:
                continue
        if not _owner_descriptor_lock(candidate):
            os.close(candidate)
            last_category = "concurrent-record-replace-lock"
        elif not _same_owner_lock_file(lock, candidate):
            _owner_descriptor_unlock(candidate)
            os.close(candidate)
            continue
        elif created:
            _write_owner_lock_descriptor(candidate, _new_replace_lock_record(owner_token))
            descriptor = candidate
        else:
            age = max(0.0, time.time() - os.fstat(candidate).st_mtime)
            record, invalid = _parse_replace_lock(_owner_descriptor_bytes(candidate))
            if invalid or record is None:
                last_category = invalid or "record-replace-lock-record-invalid"
                recover = False
            else:
                last_category = _replace_lock_owner_state(record)
                recover = age > REPLACE_LOCK_STALE_SECONDS and last_category in {
                    "record-replace-lock-owner-dead",
                    "record-replace-lock-owner-pid-reused",
                }
                recovered_category = last_category if recover else None
            if recover:
                _write_owner_lock_descriptor(candidate, _new_replace_lock_record(owner_token))
                descriptor = candidate
            else:
                _owner_descriptor_unlock(candidate)
                os.close(candidate)
        if descriptor is None:
            if time.monotonic() >= deadline:
                raise RecordReplaceLockError(last_category, f"record replacement is busy: {lock}")
            time.sleep(0.05)
    body_error = False
    try:
        yield {
            "schema_version": REPLACE_LOCK_SCHEMA_VERSION,
            "owner_pid": os.getpid(),
            "owner_token": owner_token,
            "recovered_category": recovered_category,
            "_descriptor": descriptor,
        }
    except BaseException:
        body_error = True
        raise
    finally:
        try:
            _release_replace_lock(lock, descriptor, owner_token)
        except RecordReplaceLockError:
            if not body_error:
                raise

def _powershell_command(argv: list[str]) -> str:
    escaped = [value.replace("'", "''") for value in argv]
    return "& " + " ".join(f"'{value}'" for value in escaped)

def _read_title(path: Path) -> str:
    try:
        text = path.read_text(encoding="utf-8-sig")
    except UnicodeDecodeError as exc:
        raise CkbError(f"managed knowledge note must be valid UTF-8: {path}: {exc}") from exc
    return text.splitlines()[0].removeprefix("# ").strip() if text else ""

def _locate_existing(output: Path, kind: str, title: str) -> tuple[Path, Path, Path, dict[str, Any]]:
    filename = safe_title(title) + ".md"
    relative = Path(DIRECTORY_BY_KIND[kind]) / filename
    markdown = output / "markdown" / relative
    human = output / "human" / relative
    metadata = output / "workspace-meta/notes" / (safe_title(title) + ".json")
    if not markdown.is_file() or not human.is_file():
        for other_kind, directory in DIRECTORY_BY_KIND.items():
            for root_name in ("markdown", "human"):
                candidate = output / root_name / directory / filename
                if candidate.is_file() and _read_title(candidate) == title:
                    if other_kind != kind:
                        raise CkbError(
                            f"record replace kind mismatch for exact title {title}: existing={other_kind}; requested={kind}"
                        )
        raise CkbError(f"record replace target does not exist for exact kind and title: kind={kind}; title={title}")
    if _read_title(markdown) != title or _read_title(human) != title:
        raise CkbError(f"record replace target title differs from the requested exact title: {title}")
    if markdown.read_bytes() != human.read_bytes():
        raise CkbError(f"record replace baseline human/markdown mirrors differ: {relative.as_posix()}")
    if not metadata.is_file():
        raise CkbError(f"record replace metadata is missing: {metadata}")
    record = json_load(metadata)
    if record.get("title") != title:
        raise CkbError(f"record replace metadata title differs from the requested exact title: {title}")
    if record.get("kind") != kind:
        raise CkbError(
            f"record replace kind mismatch for exact title {title}: existing={record.get('kind')}; requested={kind}"
        )
    return relative, human, markdown, record

def _copy_candidate_note_roots(output: Path, candidate_output: Path) -> None:
    for root_name in ("human", "markdown"):
        source_root = output / root_name
        target_root = candidate_output / root_name
        target_root.mkdir(parents=True, exist_ok=True)
        projection = source_root / "projection.json"
        if projection.is_file():
            shutil.copy2(projection, target_root / "projection.json")
        for directory in NOTE_DIRECTORIES:
            source = source_root / directory
            target = target_root / directory
            if source.is_dir():
                shutil.copytree(source, target)
            else:
                target.mkdir(parents=True, exist_ok=True)
    gaps = output / "workspace-meta/gaps"
    if gaps.is_dir():
        shutil.copytree(gaps, candidate_output / "workspace-meta/gaps")

def _file_state(path: Path) -> dict[str, Any]:
    return {
        "exists": path.is_file(),
        "sha256": sha256_file(path) if path.is_file() else None,
        "size": path.stat().st_size if path.is_file() else 0,
    }

def _agent_snapshot(connection: sqlite3.Connection, title: str) -> dict[str, Any]:
    note = connection.execute(
        "SELECT note_title,tag,note_file,content,token_estimate FROM notes WHERE note_title=?",
        (title,),
    ).fetchall()
    links = connection.execute(
        "SELECT note_title,page_title FROM note_links WHERE note_title=? ORDER BY page_title",
        (title,),
    ).fetchall()
    fts = connection.execute(
        "SELECT note_title,title,content FROM note_fts WHERE note_title=?",
        (title,),
    ).fetchall()
    return {"note": [list(row) for row in note], "links": [list(row) for row in links], "fts": [list(row) for row in fts]}

def _agent_candidate(baseline: dict[str, Any], title: str, text: str, links: list[str]) -> dict[str, Any]:
    if len(baseline.get("note", [])) != 1:
        raise CkbError(f"agent-index.sqlite must contain exactly one work record for title: {title}")
    row = list(baseline["note"][0])
    row[3] = text
    row[4] = _token_estimate(text)
    return {
        "note": [row],
        "links": [[title, value] for value in sorted(set(links))],
        "fts": [[title, title, text]],
    }

def _apply_agent_state(connection: sqlite3.Connection, title: str, state: dict[str, Any]) -> None:
    if len(state.get("note", [])) != 1:
        raise CkbError(f"invalid agent-index candidate for title: {title}")
    cursor = connection.execute(
        "UPDATE notes SET tag=?,note_file=?,content=?,token_estimate=? WHERE note_title=?",
        (state["note"][0][1], state["note"][0][2], state["note"][0][3], state["note"][0][4], title),
    )
    if cursor.rowcount != 1:
        raise CkbError(f"agent-index work record disappeared during replacement: {title}")
    connection.execute("DELETE FROM note_links WHERE note_title=?", (title,))
    connection.execute("DELETE FROM note_fts WHERE note_title=?", (title,))
    connection.executemany("INSERT INTO note_links(note_title,page_title) VALUES(?,?)", state.get("links", []))
    connection.executemany("INSERT INTO note_fts(note_title,title,content) VALUES(?,?,?)", state.get("fts", []))

def _sqlite_integrity(connection: sqlite3.Connection, label: str) -> None:
    integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
    foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
    if integrity != "ok" or foreign_keys:
        raise CkbError(f"{label} candidate integrity failed: integrity={integrity}; foreign_keys={foreign_keys[:10]}")

def _trial_agent(path: Path, title: str, baseline: dict[str, Any], candidate: dict[str, Any]) -> None:
    connection = sqlite3.connect(path, timeout=30)
    try:
        connection.execute("PRAGMA foreign_keys=ON")
        connection.execute("BEGIN IMMEDIATE")
        if _json_digest(_agent_snapshot(connection, title)) != _json_digest(baseline):
            raise CkbError(f"agent-index target drifted before candidate validation: {title}")
        _apply_agent_state(connection, title, candidate)
